'use strict';

const fs = require('fs');
const http = require('http');
const https = require('https');
const path = require('path');

const DEFAULT_ENDPOINT = 'http://127.0.0.1:54221/status';
const OUTPUT_FILE = path.join(__dirname, 'results', 'status.json');
const TIMEOUT_MS = 10000;
const MAX_ATTEMPTS = 3;

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function endpointCandidates() {
  const fromEnv = [
    process.env.STATUS_ENDPOINT,
    process.env.ENDPOINT,
    process.env.STATUS_URL,
    process.env.URL,
  ].find((value) => typeof value === 'string' && value.trim() !== '');
  const candidates = fromEnv ? [fromEnv.trim(), DEFAULT_ENDPOINT] : [DEFAULT_ENDPOINT];
  return [...new Set(candidates)];
}

function request(url, timeoutMs) {
  return new Promise((resolve, reject) => {
    let target;
    try {
      target = new URL(url);
    } catch (err) {
      reject(new Error(`invalid URL: ${url}`));
      return;
    }
    const client = target.protocol === 'https:' ? https : http;
    const req = client.request(
      target,
      { method: 'GET', headers: { accept: 'application/json' } },
      (res) => {
        const chunks = [];
        res.on('data', (chunk) => chunks.push(chunk));
        res.on('end', () => {
          resolve({
            statusCode: res.statusCode,
            body: Buffer.concat(chunks).toString('utf8').trim(),
          });
        });
      }
    );
    req.setTimeout(timeoutMs, () => req.destroy(new Error(`timeout after ${timeoutMs}ms`)));
    req.on('error', reject);
    req.end();
  });
}

function writeResult(status) {
  fs.mkdirSync(path.dirname(OUTPUT_FILE), { recursive: true });
  fs.writeFileSync(OUTPUT_FILE, JSON.stringify({ status }), 'utf8');
}

function readResult() {
  return JSON.parse(fs.readFileSync(OUTPUT_FILE, 'utf8'));
}

async function fetchStatus() {
  let lastError = null;
  for (const url of endpointCandidates()) {
    for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt += 1) {
      try {
        const res = await request(url, TIMEOUT_MS);
        if (res.statusCode !== 200) {
          throw new Error(`unexpected HTTP status ${res.statusCode}`);
        }
        let payload;
        try {
          payload = JSON.parse(res.body);
        } catch (err) {
          throw new Error(`invalid JSON body: ${res.body}`);
        }
        if (!payload || Number(payload.status) !== 200) {
          throw new Error(`unexpected status payload: ${res.body}`);
        }
        return { url, status: Number(payload.status) };
      } catch (err) {
        lastError = err;
        if (attempt < MAX_ATTEMPTS) {
          await sleep(300 * attempt);
        }
      }
    }
  }
  throw lastError || new Error('no endpoint could be reached');
}

function verify(expectedStatus) {
  if (!fs.existsSync(OUTPUT_FILE)) {
    return { ok: false, reason: `missing ${path.relative(__dirname, OUTPUT_FILE)}` };
  }
  let payload;
  try {
    payload = readResult();
  } catch (err) {
    return { ok: false, reason: `unreadable result file: ${err.message}` };
  }
  if (!payload || Number(payload.status) !== Number(expectedStatus)) {
    return { ok: false, reason: `result status is ${JSON.stringify(payload && payload.status)}, expected ${expectedStatus}` };
  }
  return { ok: true, reason: `results/status.json contains status=${Number(payload.status)}` };
}

async function main() {
  const args = process.argv.slice(2);

